/* A shared A4 contract for individual previews, selected reports and hosted PDFs. */
(()=>{'use strict';
const css=`@page{size:A4 portrait;margin:10mm}
html,body{margin:0!important;padding:0!important;background:#eef1f5}
body::before,body::after{display:none!important;content:none!important}
.report-page.report-page{display:block!important;box-sizing:border-box!important;width:190mm!important;max-width:190mm!important;margin:10px auto!important;padding:4mm!important;border:3px double #5c4434!important;border-radius:0!important;background:white!important;color:#17212b!important}
.report-page.report-page:not(.kp-a4-page){height:auto!important;min-height:0!important;max-height:none!important;overflow:visible!important}
.report-page :is(.report-cover,.computed-report,.report-flow-content,.sp-page-inner){height:auto!important;min-height:0!important;max-height:none!important}
.report-page :is(.table-scroll,.table-wrap,.kp-table-wrap,.basic-table-scroll,.am-scroll,.kp-table-scroll,.worksheet-scroll,.v-table-wrap){width:100%!important;min-width:0!important;max-height:none!important;height:auto!important;overflow:visible!important}
.report-page table{box-sizing:border-box!important;width:100%!important;max-width:100%!important;min-width:0!important;table-layout:fixed!important;border-collapse:collapse!important}
.report-page :is(td,th){white-space:normal!important;overflow-wrap:anywhere!important;word-break:normal;max-width:none!important;font-size:9px!important;padding:3px!important;vertical-align:top}
.report-page :is(p,li,dd,dt,h2,h3,h4){overflow-wrap:anywhere;max-width:100%}
.report-page :is(img,canvas){max-width:100%!important;height:auto}
.report-page :is(.v-report-content,.bi-facts,.sp-column){min-width:0!important;max-width:100%!important}
.report-page .v-report-content{overflow:visible!important}
.report-page :is(.south-calculations-grid,.south9-sheet,.kp-basic-calculations,.kp-feature-card,.tr-card,.pc-card,.sp-page){min-width:0!important;max-width:100%!important;width:auto!important;box-sizing:border-box!important}
.report-page :is(.south-calculations-grid,.south-calculation-grid){display:block!important}
.report-page :is(svg,.v38-chart,.north9-chart){max-width:100%!important;box-sizing:border-box!important}
.report-page :is(.ed-result,.ed-match,.pd-reference,.pd-layer,.ep-outcome-card,.ep-proof){display:block!important;height:auto!important;min-height:0!important;max-height:none!important;overflow:visible!important;position:static!important;box-sizing:border-box!important}.report-page .ed-match{break-inside:avoid!important;page-break-inside:avoid!important;margin:3mm 0!important;padding:3mm!important;border:1px solid #777!important}.report-page :is(.ed-result,.ed-results){break-inside:auto!important;page-break-inside:auto!important}.report-page .ed-match :is(p,h4,.report-expanded-details){position:static!important;height:auto!important;line-height:1.5!important;margin:2mm 0!important}.report-page .report-expanded-details{display:block!important;overflow:visible!important}
.report-page pre{white-space:pre-wrap!important;overflow-wrap:anywhere!important}
.report-page .south-calculations article{break-inside:auto!important}
.report-page .report-developer-footer{white-space:normal!important;overflow-wrap:anywhere!important;max-width:100%!important;font-size:8px!important;line-height:1.4!important}.report-page .report-fixed-developer-credit{font-weight:bold}.report-page thead{display:table-header-group!important}.report-page tfoot{display:table-footer-group!important}
.report-page :is(tr,.v-chart,.bi-facts>dl>div){break-inside:avoid!important;page-break-inside:avoid!important}
.report-page :is(h2,h3,h4){break-after:avoid!important}
.kp-print-page-frame{display:none!important}
@media print{body>.kp-print-page-frame{display:block!important;position:fixed!important;top:0!important;left:0!important;width:190mm!important;height:277mm!important;box-sizing:border-box!important;border:3px double #5c4434!important;z-index:2147483647!important;pointer-events:none!important}html,body{background:white!important;width:190mm!important;max-width:190mm!important;min-width:0!important}body:has(.report-page)::before{content:""!important;display:block!important;position:fixed!important;inset:0!important;border:3px double #5c4434!important;box-sizing:border-box!important;pointer-events:none!important;z-index:2147483647!important}.report-page.report-page{border:0!important;padding:4mm!important}.no-print,.kp-preview-tools,.preview-tools,.report-selection-preview-tools,.notepad-preview-tools{display:none!important}.report-page.report-page{margin:0!important;zoom:1!important;box-shadow:none!important;break-after:page!important;page-break-after:always!important}.report-page.report-page:last-child,.report-page.report-page:has(+.kp-print-page-frame:last-child){break-after:auto!important;page-break-after:auto!important}}`;
function deduplicate(root){for(const page of root.querySelectorAll('[data-report-section="south9"]')){if(page.querySelector('[data-report-id="south-position-tables"],#south-position-tables,.south-calculations'))page.querySelectorAll('[data-report-id="kp-basic-calculations"],#kp-basic-calculations').forEach(n=>n.remove());}}
function prepare(doc){if(!doc?.head)return;deduplicate(doc);if(!doc.querySelector('body>.kp-print-page-frame')){const frame=doc.createElement('div');frame.className='kp-print-page-frame';frame.setAttribute('aria-hidden','true');doc.body.append(frame);}for(const details of doc.querySelectorAll('.report-page details')){const box=doc.createElement('div');box.className='report-expanded-details';for(const child of [...details.childNodes]){if(child.nodeType===1&&child.tagName==='SUMMARY'){const heading=doc.createElement('p');heading.className='report-detail-heading';heading.textContent=child.textContent;box.append(heading);}else box.append(child);}details.replaceWith(box);}window.KPDeveloperCredit?.apply(doc);let style=doc.getElementById('kp-report-a4-contract');if(!style){style=doc.createElement('style');style.id='kp-report-a4-contract';doc.head.append(style);}style.textContent=css;const language=window.KPPreferences?.get().language||document.documentElement.dataset.kpLanguage||'english';doc.documentElement.lang=window.KPLanguage?.languages?.find?.(l=>l.value===language)?.code||(language==='marathi'?'mr':'en');doc.documentElement.dataset.kpLanguage=language;window.KPLanguage?.localize(doc);doc.querySelectorAll('.report-page .v38-name,.report-page .v38-degree').forEach(n=>n.style.setProperty('font-size',n.classList.contains('v38-name')?'9px':'8px','important'));doc.querySelectorAll('.report-page [data-report-id="basic"],.report-page .pc-entry-pair').forEach(n=>n.remove());}
function install(){const render=window.renderReport;if(render)window.renderReport=function(...args){const result=render.apply(this,args);deduplicate(document.getElementById('printReport'));return result;};window.renderReport?.();const old=window.KPReportPreview;if(old)window.KPReportPreview=Object.freeze({...old,open(id){const w=old.open(id==='basic'?'vedic-information':id);if(w){prepare(w.document);w.document.fonts.ready.then(()=>{for(const page of w.document.querySelectorAll('.kp-a4-page'))window.KPA4Preview?.fit(w.document,page);});}return w;}});}
window.KPA4Reports=Object.freeze({css,prepare});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(install,0));else install();
})();
